def dedupe(listings: list[dict]) -> list[dict]:
    def normalize_title(title):
        return " ".join(str(title).split()).lower()

    groups = {}
    for idx, item in enumerate(listings):
        key = (normalize_title(item["title"]), item["price"])
        groups.setdefault(key, []).append((idx, item))

    keep_indices = set()
    for entries in groups.values():
        best_idx, _ = min(entries, key=lambda entry: (entry[1]["date"], entry[0]))
        keep_indices.add(best_idx)

    return [item for idx, item in enumerate(listings) if idx in keep_indices]

