    if not csv_text:
        return totals

    text = csv_text.lstrip("\ufeff")
    reader = csv.DictReader(io.StringIO(text))
    for row in reader:
        if row is None:
            continue
        price_raw = (row.get("price") or "").strip()
        payment = (row.get("payment") or "").strip().lower()
        if price_raw == "" or payment == "":
            continue
        price = int(price_raw.replace(",", ""))
        totals[payment] = totals.get(payment, 0) + price
    return totals

